SCORER_SOURCE="for key, result in results.items():\n    tool_calls = result['tool_calls']\n    answer = result['data']['answer']\n    if type(answer) == list:\n        answer = answer[0]\n    answer_name = answer['name']\n    answer_parameters = answer['parameters']\n    score = 0\n    if len(tool_calls) != 1:\n        pass\n    if True:\n        try:\n            for tool_call in tool_calls:\n                if type(tool_call) == str:\n                    tool_call = json.loads(tool_call)\n                predict = tool_call\n                if 'name' not in predict or 'parameters' not in predict:\n                    name = answer_name\n                    parameters = predict\n                else:\n                    name = predict['name']\n                    parameters = predict['parameters']\n                if name == answer_name and parameters == answer_parameters:\n                    score += 1\n                    break\n        except Exception as e:\n            print('Error parsing tool call:', tool_call)\n    result['score'] = score\n    scores[key] = result"
